#pragma once

// Interface between AOT-translated guest code (generated by dekui_aot) and the
// emulator. Generated sources include only this header, so it must stay
// self-contained.
//
// Guest state mirrors Dynarmic's arm64 A32JitState field for field, so every
// IR operation keeps exactly the semantics Dynarmic gives it and state moves
// between Dynarmic, the interpreter and AOT code with the same conversions.

#include <cstdint>

namespace DekuiAot::Abi {

/// Bumped whenever State, Env or the block calling convention change.
/// Generated code records the version it was built against.
constexpr std::uint32_t Version = 1;

struct Env;

struct State {
    std::uint32_t cpsr_nzcv = 0;
    std::uint32_t cpsr_q = 0;
    std::uint32_t cpsr_jaifm = 0;
    std::uint32_t cpsr_ge = 0;  ///< One 0x00/0xFF byte per GE bit.
    std::uint32_t fpsr = 0;     ///< FPSCR cumulative flags (0x0800009F).
    std::uint32_t fpsr_nzcv = 0;
    std::uint32_t regs[16]{};
    std::uint32_t upper_location_descriptor = 0;
    alignas(16) std::uint32_t ext_regs[64]{};
    std::uint32_t exclusive_state = 0;

    /// Cycles left in this slice. Blocks subtract their cost and keep chaining
    /// while this stays positive.
    std::int64_t ticks = 0;
    /// Non-zero requests a return to the dispatcher at the next CheckHalt.
    volatile std::uint32_t halt = 0;
    /// Scratch for A32SetCheckBit / Term::CheckBit.
    std::uint8_t check_bit = 0;

    const Env* env = nullptr;
    /// Owner of this state (the emulator's per-core runner).
    void* host_context = nullptr;

    std::uint64_t Descriptor() const {
        return regs[15] | (std::uint64_t(upper_location_descriptor) << 32);
    }

    std::uint32_t Cpsr() const {
        std::uint32_t cpsr = cpsr_nzcv | cpsr_q | cpsr_jaifm;
        cpsr |= (cpsr_ge >> 31 & 1) << 19 | (cpsr_ge >> 23 & 1) << 18 |
                (cpsr_ge >> 15 & 1) << 17 | (cpsr_ge >> 7 & 1) << 16;
        cpsr |= (upper_location_descriptor >> 1 & 1) << 9 | (upper_location_descriptor & 1) << 5;
        cpsr |= upper_location_descriptor & 0xFC00;
        cpsr |= (upper_location_descriptor & 0x0300) << 17;
        return cpsr;
    }

    void SetCpsr(std::uint32_t cpsr) {
        cpsr_nzcv = cpsr & 0xF0000000;
        cpsr_q = cpsr & (1u << 27);
        cpsr_ge = (cpsr >> 19 & 1 ? 0xFF000000 : 0) | (cpsr >> 18 & 1 ? 0x00FF0000 : 0) |
                  (cpsr >> 17 & 1 ? 0x0000FF00 : 0) | (cpsr >> 16 & 1 ? 0x000000FF : 0);
        upper_location_descriptor &= 0xFFFF0000;
        upper_location_descriptor |= (cpsr >> 9 & 1) << 1 | (cpsr >> 5 & 1);
        upper_location_descriptor |= cpsr & 0xFC00;
        upper_location_descriptor |= (cpsr >> 17) & 0x0300;
        cpsr_jaifm = cpsr & 0x010001DF;
    }

    std::uint32_t Fpscr() const {
        return (upper_location_descriptor & 0xFFFF0000) | fpsr | fpsr_nzcv;
    }

    void SetFpscr(std::uint32_t fpscr) {
        fpsr_nzcv = fpscr & 0xF0000000;
        fpsr = fpscr & 0x0800009F;
        upper_location_descriptor =
            (upper_location_descriptor & 0x0000FFFF) | (fpscr & 0x07F70000);
    }
};

/// Callbacks into the emulator. `state` is passed so the runtime can find its
/// own context (State is embedded in it) and account ticks around calls.
struct Env {
    /// Citra's 4 KiB page pointer table; a null entry means "use the callback".
    std::uint8_t* const* page_table = nullptr;

    std::uint8_t (*read8)(State*, std::uint32_t);
    std::uint16_t (*read16)(State*, std::uint32_t);
    std::uint32_t (*read32)(State*, std::uint32_t);
    std::uint64_t (*read64)(State*, std::uint32_t);
    void (*write8)(State*, std::uint32_t, std::uint8_t);
    void (*write16)(State*, std::uint32_t, std::uint16_t);
    void (*write32)(State*, std::uint32_t, std::uint32_t);
    void (*write64)(State*, std::uint32_t, std::uint64_t);

    std::uint8_t (*exclusive_read8)(State*, std::uint32_t);
    std::uint16_t (*exclusive_read16)(State*, std::uint32_t);
    std::uint32_t (*exclusive_read32)(State*, std::uint32_t);
    std::uint64_t (*exclusive_read64)(State*, std::uint32_t);
    /// Global exclusive monitor (Dynarmic's ReadAndMark / DoExclusiveOperation).
    /// Generated code keeps State::exclusive_state itself. Writes return 0 on
    /// success and 1 on failure, like STREX.
    std::uint32_t (*exclusive_write8)(State*, std::uint32_t, std::uint8_t);
    std::uint32_t (*exclusive_write16)(State*, std::uint32_t, std::uint16_t);
    std::uint32_t (*exclusive_write32)(State*, std::uint32_t, std::uint32_t);
    std::uint32_t (*exclusive_write64)(State*, std::uint32_t, std::uint64_t);

    /// The runtime adds the cycles consumed so far and refreshes `ticks`.
    void (*call_svc)(State*, std::uint32_t swi);
    void (*exception_raised)(State*, std::uint32_t pc, std::uint32_t exception);
    /// Raw Dynarmic CoprocInfo bytes (coproc, two, opc1, CRn, CRm, opc2 ...).
    void (*coproc_internal)(State*, std::uint64_t info);
    void (*coproc_send_one)(State*, std::uint64_t info, std::uint32_t);
    void (*coproc_send_two)(State*, std::uint64_t info, std::uint32_t, std::uint32_t);
    std::uint32_t (*coproc_get_one)(State*, std::uint64_t info);
    std::uint64_t (*coproc_get_two)(State*, std::uint64_t info);
    void (*coproc_load)(State*, std::uint64_t info, std::uint32_t address);
    void (*coproc_store)(State*, std::uint64_t info, std::uint32_t address);
};

/// Every translated block has this signature. It runs the block (and any
/// blocks it chains into while `ticks` stays positive), leaves PC and the upper
/// location descriptor in `state`, and returns state->Descriptor().
using BlockFn = std::uint64_t (*)(State*);

struct BlockEntry {
    std::uint64_t descriptor;
    BlockFn fn;
};

/// Exported by the generated sources.
struct Module {
    std::uint32_t abi_version;
    const char* code_sha256;   ///< Image the code was generated from.
    std::uint32_t code_size;   ///< Bytes of that image covered by code_sha256.
    const BlockEntry* blocks;  ///< Sorted by descriptor.
    std::uint32_t block_count;
};

} // namespace DekuiAot::Abi
